-- ================================================================
-- Malta (MT) ES/DE/FR translations, completing 475 (milestones),
-- 477 (deep-dive content) and 478 (launch story) against their
-- English content. Written 10 Aug 2026. Separate migration file, so
-- every deep-dive translation row looks up its parent row via a JOIN
-- on stable identifying columns (country code / section / sort_order
-- / English title text), never via (SELECT MAX(id) ...) -- pattern
-- reference: 471 (Bulgaria), 472 (Estonia).
-- milestone_translations and story_translations have natural string
-- PKs (milestone_id / story_id), so those rows are plain INSERT OR
-- IGNORE statements keyed on the hardcoded id strings from 475/478 --
-- no JOIN needed. INSERT OR IGNORE throughout.
--
-- Malta has no deep_dive_lifecycle_* or deep_dive_penalty_rows rows
-- (see 477's header -- no clearance flow to diagram, and no penalty
-- regime exists because no mandate exists to penalize), so those
-- tables are not touched here. tracking_source_translations was
-- already completed for all four languages in 479 -- not touched
-- here.
--
-- Kept unchanged across languages: MTCA, Peppol, EN 16931,
-- BIS Billing 3.0, UBL, Pagero, ViDA, Council Directive (EU)
-- 2025/516, "eInvoicing4Islands", Financial Administration and
-- Audit Act (Cap. 174), Local Councils Act (Cap. 363), Subsidiary
-- Legislation 601.10, Ministry for Finance. Dates localized per
-- language convention (es "30 de noviembre de 2018", de "30.
-- November 2018", fr "30 novembre 2018"), consistent with how 471
-- handled Bulgarian dates. mandate_summary_icon is the unchanged
-- '🇲🇹' flag emoji in every language. The direct MTCA quotes
-- ("actively studying...", "ViDA-ready by 2030") are translated as
-- quoted paraphrase, keeping the quotation-mark framing since the
-- site attributes them directly to MTCA's own wording. Malta remains
-- the thinnest content set on this site in every language -- no
-- padding added in translation.


-- ==================== es ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es',
  'Sin mandato B2B, sin sistema de reporte nacional — el B2G es solo un requisito de capacidad de recepción',
  'Esta página de análisis refleja el régimen de facturación electrónica de Malta, tal como se confirma a través de la ficha país de facturación electrónica de la Comisión Europea para Malta, la página de e-Invoicing del Ministerio de Finanzas de Malta y la propia página "E-Invoicing and DRR" de la Administración Tributaria y Aduanera de Malta (MTCA) (recuperada y confirmada de forma independiente en esta ronda de investigación), con fecha de 10 de agosto de 2026, y se ofrece a título informativo general, no como asesoría legal o tributaria. Confirme los requisitos vigentes directamente con la MTCA (mtca.gov.mt) o con un asesor fiscal maltés antes de basar en esta página sus decisiones de cumplimiento.',
  'Malta transpuso la directiva de facturación electrónica B2G de la UE mediante avisos legales a finales de 2018 — pero incluso esa obligación es más estrecha que la de la mayoría de sus pares en la UE: exige únicamente que las entidades adjudicadoras públicas *puedan recibir* facturas electrónicas estructuradas, no que los proveedores las envíen. Malta nunca ha construido un mandato nacional de facturación electrónica B2B, ninguna plataforma de clearance, ni ningún sistema de control continuo de las transacciones. A fecha de esta ronda de investigación, la Administración Tributaria y Aduanera de Malta se describe a sí misma como "estudiando activamente" la facturación electrónica y el reporte en tiempo real, con el objetivo de estar preparada para el suelo de ViDA de la UE de 2030, en lugar de un mandato nacional anterior.',
  'Malta acepta facturas electrónicas estructuradas conformes con la norma EN 16931 para el B2G, transmitidas a través de la red Peppol (Peppol BIS Billing 3.0, UBL) mediante un punto de acceso certificado, o introducidas manualmente a través de un portal. Malta no dispone de una plataforma nacional de facturación electrónica propia — en su lugar, el Ministerio de Finanzas contrató a Pagero como su proveedor de servicios Peppol certificado tras un proyecto de infraestructura financiado por la UE. No existe ningún formato de reporte independiente que describir, porque Malta no tiene ningún sistema de reporte nacional.',
  'El alcance del B2G cubre únicamente el lado de la recepción: las entidades adjudicadoras deben ser capaces de procesar facturas electrónicas para la contratación pública por encima de los umbrales de la UE; los proveedores no están obligados a enviarlas. Hoy no existe ningún alcance de facturación electrónica B2B o B2C de ningún tipo, porque no existe ningún mandato.',
  'Para la mayoría de las empresas maltesas, hoy no hay realmente nada que hacer en materia de facturación electrónica más allá de una conciencia general de la situación — la tarea práctica es vigilar la eventual propuesta nacional de la MTCA, en lugar de prepararse para una obligación existente.',
  'No existe ningún régimen sancionador de facturación electrónica o de reporte digital en Malta — confirmado tanto por la ficha de la Comisión Europea como por la propia página de la MTCA. Esto se deriva directamente de que no existe ningún mandato B2B ni ninguna obligación B2G del lado del proveedor que sancionar.',
  'Malta tiene el régimen de facturación electrónica más reducido de todos los Estados miembros de la UE seguidos en este sitio: la facturación electrónica B2G solo exige que las entidades adjudicadoras puedan recibir facturas estructuradas (avisos legales, finales de 2018) — no hay ningún mandato para el proveedor, ningún requisito nacional B2B, ninguna plataforma de clearance y ningún sistema de reporte de ningún tipo. La Administración Tributaria y Aduanera de Malta confirma que está "estudiando activamente" la facturación electrónica y el reporte en tiempo real con el objetivo de estar "preparada para ViDA en 2030", en lugar de perseguir un mandato nacional anterior. El suelo confirmado a escala de la UE sigue siendo el 1 de julio de 2030 (ViDA) para el B2B transfronterizo.',
  '🇲🇹'
FROM countries WHERE code = 'MT';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '30 nov 2018', 'Avisos legales que transponen la directiva de facturación electrónica B2G de la UE' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'MT' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', 'Solo recepción', 'Las entidades deben aceptar facturas electrónicas — los proveedores no están obligados a enviarlas' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'MT' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', 'Sin mandato', 'Sin mandato de facturación electrónica B2B, sin fecha objetivo, sin anteproyecto de ley' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'MT' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', 'Sin plataforma', 'Solo Peppol a través de Pagero — sin sistema nacional propio' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'MT' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '2030', '"Preparada para ViDA" es el objetivo declarado por la propia MTCA, según su propio sitio web' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'MT' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Formato y red B2G', '[["Formato", "Factura electrónica estructurada conforme con la norma EN 16931"], ["Red", "Peppol (Peppol BIS Billing 3.0, UBL) — sin plataforma nacional propia"], ["Proveedor de servicios", "Pagero, contratado por el Ministerio de Finanzas tras el proyecto financiado por la UE \"eInvoicing4Islands\""], ["Opciones de envío", "Transmisión estructurada a través de un punto de acceso Peppol certificado, o introducción manual a través de un portal"]]', 'Malta es inusual entre los países de la UE seguidos en este sitio por no haber construido ninguna plataforma propia — depende enteramente de la red Peppol compartida y de un único proveedor de servicios contratado.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'MT' AND cd.section = 'file_format' AND dct.title = 'B2G format & network';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Lo que realmente se exige hoy', '[["Entidades adjudicadoras", "Deben poder recibir y procesar facturas electrónicas EN 16931 para la contratación pública por encima de los umbrales de la UE — desde nov/dic de 2018 (administración central), abr de 2020 (subcentral, de fuente sectorial)"], ["Proveedores de entidades públicas", "NO están obligados a enviar facturas electrónicas — pueden seguir presentando papel/PDF"], ["B2B", "Sin ningún requisito de ningún tipo — enteramente voluntario, por acuerdo mutuo"], ["B2C", "No está cubierto por ninguna norma"]]', 'Esta es la obligación B2G más estrecha de todos los países de la UE seguidos en este sitio — la mayoría de sus pares exigen tanto una capacidad de recepción COMO un mandato de envío del lado del proveedor; Malta solo tiene la primera.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'MT' AND cd.section = 'scope_transmission' AND dct.title = 'What''s actually required today';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Lo que dice la MTCA sobre el futuro', '[["Estado", "\"Estudiando activamente la implementación de la facturación electrónica y el reporte en tiempo real\" (palabras textuales de la MTCA)"], ["Objetivo", "\"Garantizar que Malta esté preparada para ViDA en 2030\" (palabras textuales de la MTCA)"], ["Actividad reciente", "El proyecto financiado por el TSI \"Reforzar el cumplimiento tributario mediante el reporte en tiempo real en Malta\" celebró un acto de clausura con las partes interesadas el 5 de junio de 2025"], ["Sin fecha nacional comprometida", "Ni el Plan Estratégico 2023-2025 de la MTCA ni el Documento de Consulta Prepresupuestaria 2026 del Gobierno indican una fecha concreta de mandato para Malta"]]', 'A diferencia de la controvertida cifra de "2028" de Lituania, las propias fuentes de Malta son coherentes e inequívocas: no existe ninguna fecha objetivo nacional en absoluto, solo una alineación con el suelo de la UE de 2030.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'MT' AND cd.section = 'scope_transmission' AND dct.title = 'What MTCA says about the future';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '⚖️ No existe ningún régimen sancionador — no hay nada que sancionar', NULL, NULL, 'Malta no tiene ningún mandato de facturación electrónica B2B, ninguna obligación B2G del lado del proveedor, ni ningún requisito de reporte digital — por lo que no hay ningún baremo de multas vinculado a ninguno de ellos. Tanto la ficha de la Comisión Europea como la propia página de la MTCA lo confirman directamente en lugar de dejarlo a la deducción.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'MT' AND cd.section = 'penalties_related' AND dct.title = '⚖️ No penalty regime exists — there is nothing to penalize';

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Si vende a entidades públicas maltesas, sepa que la facturación electrónica es opcional, no obligatoria', 'Las entidades adjudicadoras maltesas pueden recibir facturas electrónicas estructuradas EN 16931 a través de Peppol, pero usted no está legalmente obligado a enviarlas — las facturas en papel o PDF siguen siendo aceptables, salvo que una entidad adjudicadora concreta solicite lo contrario.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'MT' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Si desea facturar electrónicamente a una entidad pública maltesa, utilice Peppol', 'Envíe a través de un punto de acceso Peppol certificado (el Ministerio de Finanzas de Malta contrató a Pagero como su proveedor) o use la opción de introducción manual en el portal cuando esté disponible.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'MT' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Hoy no se requiere ninguna acción B2B', 'No existe ningún mandato nacional de facturación electrónica B2B para el que prepararse, y la MTCA no ha indicado ninguna fecha objetivo más allá de una alineación general con el suelo de ViDA de la UE de 2030.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'MT' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Esté atento a la eventual propuesta nacional de la MTCA', 'Vigile directamente la página "E-Invoicing and DRR" de mtca.gov.mt — es la fuente oficial más clara para saber cuándo la fase preparatoria de Malta se convierta en una propuesta real y con fecha.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'MT' AND sp.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'Administración Tributaria y Aduanera de Malta -- E-Invoicing and DRR' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'MT' AND pt.sort_order = 0;
