INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'mt-b2g-2018', 'es',
  'Las entidades adjudicadoras públicas deben poder recibir facturas electrónicas',
  'Los avisos legales que transponen la Directiva 2014/55/UE de la UE se publicaron el 30 de noviembre de 2018 (según la propia ficha de la Comisión Europea; el portal legislativo oficial de Malta muestra por separado una fecha de promulgación de 19 de diciembre de 2018 para el reglamento de aplicación, Subsidiary Legislation 601.10 — se registran aquí ambas fechas en lugar de elegir una en silencio), modificando la Financial Administration and Audit Act (Cap. 174) y la Local Councils Act (Cap. 363). Esto NO es un mandato para el proveedor: la obligación vinculante es únicamente que las entidades adjudicadoras maltesas centrales, subcentrales y locales deban poder recibir y procesar facturas electrónicas conformes con la norma EN 16931 para la contratación pública por encima de los umbrales de la UE — los proveedores no están legalmente obligados a enviarlas. Malta no dispone de una plataforma nacional centralizada; depende de la red Peppol, con el Ministerio de Finanzas contratando a Pagero como su proveedor de servicios Peppol certificado tras el proyecto financiado por la UE "eInvoicing4Islands" (2019-2021).', '["Contexto histórico — confirma que los organismos públicos malteses PUEDEN recibir facturas electrónicas, no que los proveedores deban enviarlas", "Los proveedores de organismos públicos malteses pueden presentar facturas electrónicas estructuradas EN 16931 a través de un punto de acceso Peppol o introducir las facturas manualmente a través del portal correspondiente"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'mt-b2g-subcentral-2020', 'es',
  'Plazo de capacidad de recepción de las entidades adjudicadoras subcentrales',
  'Las fuentes sectoriales citan repetidamente abril de 2020 como el momento en que las entidades adjudicadoras públicas subcentrales de Malta debían ser capaces de recibir facturas electrónicas EN 16931 — coherente con la estructura general de plazos escalonados de la Directiva 2014/55/UE de la UE (entidades centrales antes del 18 abr 2019, subcentrales antes del 18 abr 2020), pero no se encontró indicado explícitamente en ninguna página oficial del Gobierno maltés durante esta ronda de investigación, por lo que se registra como de fuente sectorial y no como confirmado oficialmente.', '[]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'mt-peppol-pagero', 'es',
  'Pagero, contratado como proveedor de servicios Peppol de Malta',
  'Durante el proyecto financiado por la UE "eInvoicing4Islands" (de junio de 2019 hasta aproximadamente el tercer trimestre de 2021), el Ministerio de Finanzas llevó a cabo un concurso público y contrató a Pagero para prestar el servicio de red Peppol y facturación electrónica de Malta — confirmado por el propio comunicado de prensa de Pagero. Esto proporcionó a Malta su infraestructura de facturación electrónica sin construir una plataforma nacional a medida, a diferencia de la mayoría de los demás países de la UE seguidos.', '[]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'mt-b2b-voluntary', 'es',
  'La facturación electrónica B2B sigue siendo voluntaria — sin mandato, sin fecha objetivo, sin anteproyecto de ley',
  'Malta no tiene ningún mandato de facturación electrónica entre empresas ni ninguna fecha comprometida para uno. La propia página de la Administración Tributaria y Aduanera de Malta (MTCA) afirma: "La Administración Tributaria y Aduanera de Malta (MTCA) está estudiando activamente la implementación de la facturación electrónica y el reporte en tiempo real... garantizando que Malta esté preparada para ViDA en 2030" — un lenguaje preparatorio, no un plan legislado. La propia ficha de la Comisión Europea confirma lo mismo: "no existe ningún mandato entre empresas (B2B)... el uso sigue siendo opcional". No existe ningún régimen sancionador por incumplimiento en materia de facturación electrónica o de reporte digital, porque actualmente no existe tal obligación que hacer cumplir.', '["No se requiere ninguna acción nacional de facturación electrónica B2B por el momento", "Vigile la MTCA (mtca.gov.mt) por si se anuncia en el futuro un mandato nacional — ninguno existe a fecha de esta ronda de investigación"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'mt-vida-2030', 'es',
  'La facturación electrónica B2B transfronteriza y el reporte digital de ViDA pasan a ser obligatorios (derecho de la UE confirmado)',
  'Desde el 1 de julio de 2030, en virtud de la Directiva (UE) 2025/516 del Consejo, la facturación electrónica estructurada y el reporte digital pasan a ser obligatorios para todas las entregas B2B intracomunitarias. Es la misma fecha que la propia MTCA menciona como su objetivo de "preparación para ViDA" — las propias declaraciones públicas de Malta describen que se está trabajando hacia este suelo de la UE, no hacia un mandato nacional anterior.', '["Prepárense para la facturación electrónica estructurada obligatoria en todo el comercio B2B intracomunitario desde mediados de 2030", "La infraestructura actual de Malta (Peppol a través de Pagero, procedente del despliegue B2G) proporciona una base técnica de partida, aunque aún no existe ningún plan de despliegue B2B nacional"]'
);

INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES (
  '2025-06-05-malta-tsi-project-closes', 'es',
  'Malta concluye su proyecto piloto de reporte en tiempo real — sigue sin haber mandato B2B sobre la mesa',
  'La administración tributaria de Malta concluyó un proyecto financiado por la UE sobre la preparación para el reporte en tiempo real, reafirmando que el país solo está "estudiando activamente" la facturación electrónica y el reporte digital, sin ningún mandato B2B nacional, fecha objetivo o anteproyecto de ley — apuntando en cambio a una preparación general para el plazo de ViDA de la UE de 2030.',
  '<h3>🇲🇹 Malta concluye su proyecto piloto de reporte en tiempo real — sigue sin haber mandato B2B sobre la mesa</h3>
<p>El 5 de junio de 2025, la Administración Tributaria y Aduanera de Malta (MTCA) celebró el acto de clausura con las partes interesadas de un proyecto del Instrumento de Apoyo Técnico (TSI) de la UE, "Reforzar el cumplimiento tributario mediante el reporte en tiempo real en Malta". Es la prueba reciente más concreta de la postura de Malta sobre la facturación electrónica: exploratoria, no comprometida. La propia página de la MTCA afirma claramente que está "estudiando activamente la implementación de la facturación electrónica y el reporte en tiempo real", con el objetivo explícito de "garantizar que Malta esté preparada para ViDA en 2030" — no un mandato nacional anterior.</p>
<p>Eso deja a Malta con uno de los regímenes de facturación electrónica más reducidos entre los países de la UE seguidos: los avisos legales de finales de 2018 exigen que las entidades adjudicadoras públicas *puedan recibir* facturas electrónicas estructuradas, pero los proveedores no están obligados a enviarlas, no existe ningún mandato B2B nacional de ningún tipo, y Malta no tiene ninguna plataforma propia — depende en cambio de la red Peppol a través de un proveedor de servicios contratado (Pagero). Tanto la propia ficha de la Comisión Europea como la página de la MTCA confirman que tampoco existe ningún régimen sancionador, por la sencilla razón de que aún no existe ningún mandato que hacer cumplir.</p>'
);


-- ==================== de ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de',
  'Kein B2B-Mandat, kein inländisches Meldesystem — B2G ist lediglich eine Empfangsfähigkeits-Anforderung',
  'Diese Analyseseite spiegelt Maltas E-Invoicing-Regime wider, wie es über das eInvoicing-Länderfactsheet der Europäischen Kommission für Malta, die e-Invoicing-Seite des maltesischen Finanzministeriums und die eigene Seite "E-Invoicing and DRR" der maltesischen Steuer- und Zollbehörde (MTCA) (in dieser Rechercherunde unabhängig erneut abgerufen und bestätigt) bestätigt wurde, mit Stand 10. August 2026, und dient allgemeinen Informationszwecken, nicht als Rechts- oder Steuerberatung. Bestätigen Sie aktuelle Anforderungen direkt bei der MTCA (mtca.gov.mt) oder bei einem maltesischen Steuerberater, bevor Sie sich bei Compliance-Entscheidungen auf diese Seite verlassen.',
  'Malta setzte die B2G-E-Invoicing-Richtlinie der EU durch Rechtsverordnungen Ende 2018 um — doch selbst diese Pflicht ist enger gefasst als bei den meisten EU-Vergleichsländern: Sie verlangt lediglich, dass öffentliche Vergabestellen strukturierte E-Rechnungen *empfangen können*, nicht dass Lieferanten sie versenden müssen. Malta hat nie ein inländisches B2B-E-Invoicing-Mandat, eine Clearance-Plattform oder ein fortlaufendes Transaktionskontrollsystem eingeführt. Zum Zeitpunkt dieser Rechercherunde beschreibt sich die maltesische Steuer- und Zollbehörde selbst als "aktiv prüfend" in Bezug auf E-Invoicing und Echtzeit-Reporting, mit dem Ziel, für die 2030er ViDA-Untergrenze der EU bereit zu sein, statt für ein früheres inländisches Mandat.',
  'Malta akzeptiert EN-16931-konforme strukturierte E-Rechnungen für B2G, übermittelt über das Peppol-Netzwerk (Peppol BIS Billing 3.0, UBL) über einen zertifizierten Access Point oder manuell über ein Portal eingegeben. Malta hat keine eigene, maßgeschneiderte nationale E-Invoicing-Plattform — stattdessen beauftragte das Finanzministerium Pagero als zertifizierten Peppol-Dienstanbieter im Anschluss an ein EU-gefördertes Infrastrukturprojekt. Es gibt kein separates Meldeformat zu beschreiben, da Malta über kein inländisches Meldesystem verfügt.',
  'Der B2G-Anwendungsbereich deckt nur die Empfangsseite ab: Vergabestellen müssen in der Lage sein, E-Rechnungen für Beschaffungen oberhalb der EU-Schwellenwerte zu verarbeiten; Lieferanten sind nicht verpflichtet, sie zu versenden. Es gibt heute keinerlei B2B- oder B2C-E-Invoicing-Anwendungsbereich, weil kein Mandat existiert.',
  'Für die meisten maltesischen Unternehmen gibt es beim E-Invoicing bislang wirklich nichts zu tun, abseits allgemeiner Aufmerksamkeit — die praktische Aufgabe besteht darin, den eventuellen inländischen Vorschlag der MTCA im Blick zu behalten, statt sich auf eine bestehende Pflicht vorzubereiten.',
  'In Malta besteht kein E-Invoicing- oder Meldepflicht-Bußgeldregime — bestätigt sowohl durch das Factsheet der Europäischen Kommission als auch durch die eigene Seite der MTCA. Dies folgt unmittelbar daraus, dass es kein B2B-Mandat und keine lieferantenseitige B2G-Pflicht gibt, deren Nichteinhaltung sanktioniert werden könnte.',
  'Malta hat das schwächste E-Invoicing-Regime aller auf dieser Website erfassten EU-Mitgliedstaaten: Die B2G-E-Rechnungsstellung verlangt von Vergabestellen lediglich, strukturierte Rechnungen empfangen zu können (Rechtsverordnungen, Ende 2018) — es gibt kein Lieferantenmandat, keine inländische B2B-Anforderung, keine Clearance-Plattform und kein Meldesystem jeglicher Art. Die maltesische Steuer- und Zollbehörde bestätigt, dass sie E-Invoicing und Echtzeit-Reporting "aktiv prüft", mit dem Ziel, "bis 2030 ViDA-bereit" zu sein, statt ein früheres inländisches Mandat zu verfolgen. Die bestätigte EU-weite Untergrenze bleibt der 1. Juli 2030 (ViDA) für grenzüberschreitendes B2B.',
  '🇲🇹'
FROM countries WHERE code = 'MT';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '30. Nov. 2018', 'Rechtsverordnungen zur Umsetzung der EU-B2G-E-Invoicing-Richtlinie' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'MT' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', 'Nur Empfang', 'Behörden müssen E-Rechnungen akzeptieren — Lieferanten sind nicht zum Versand verpflichtet' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'MT' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', 'Kein Mandat', 'Kein B2B-E-Invoicing-Mandat, kein Zieldatum, kein Gesetzentwurf' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'MT' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', 'Keine Plattform', 'Nur Peppol über Pagero — kein eigenes nationales System' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'MT' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '2030', '"ViDA-bereit" ist das von der MTCA selbst genannte Ziel, laut ihrer eigenen Website' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'MT' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'B2G-Format & -Netzwerk', '[["Format", "EN-16931-konforme strukturierte E-Rechnung"], ["Netzwerk", "Peppol (Peppol BIS Billing 3.0, UBL) — keine eigene nationale Plattform"], ["Dienstanbieter", "Pagero, beauftragt durch das Finanzministerium im Anschluss an das EU-geförderte Projekt \"eInvoicing4Islands\""], ["Übermittlungsoptionen", "Strukturierte Übertragung über einen zertifizierten Peppol Access Point, oder manuelle Eingabe über ein Portal"]]', 'Malta ist unter den erfassten EU-Ländern ungewöhnlich, da es keine eigene Plattform aufgebaut hat — es verlässt sich vollständig auf das gemeinsame Peppol-Netzwerk und einen einzigen beauftragten Dienstanbieter.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'MT' AND cd.section = 'file_format' AND dct.title = 'B2G format & network';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Was heute tatsächlich verlangt wird', '[["Vergabestellen", "Müssen EN-16931-E-Rechnungen für Beschaffungen oberhalb der EU-Schwellenwerte empfangen und verarbeiten können — seit Nov./Dez. 2018 (zentral), April 2020 (nachgeordnet, aus Branchenquellen)"], ["Lieferanten öffentlicher Stellen", "NICHT verpflichtet, E-Rechnungen zu versenden — Papier/PDF bleibt weiterhin möglich"], ["B2B", "Keinerlei Anforderung — vollständig freiwillig, nach gegenseitiger Vereinbarung"], ["B2C", "Von keiner Vorschrift erfasst"]]', 'Dies ist die engste B2G-Pflicht unter allen erfassten EU-Ländern — die meisten Vergleichsländer verlangen sowohl eine Empfangsfähigkeit ALS AUCH ein lieferantenseitiges Versandmandat; Malta hat nur Ersteres.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'MT' AND cd.section = 'scope_transmission' AND dct.title = 'What''s actually required today';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Was die MTCA über die Zukunft sagt', '[["Status", "\"Prüft aktiv die Einführung von E-Invoicing und Echtzeit-Reporting\" (wörtlich von der MTCA)"], ["Ziel", "\"Sicherstellen, dass Malta bis 2030 ViDA-bereit ist\" (wörtlich von der MTCA)"], ["Jüngste Aktivität", "Das TSI-geförderte Projekt \"Stärkung der Steuer-Compliance durch Echtzeit-Reporting in Malta\" hielt am 5. Juni 2025 eine Abschlussveranstaltung mit Stakeholdern ab"], ["Kein festgelegtes inländisches Datum", "Weder der Strategieplan 2023-2025 der MTCA noch das Vorbudget-Konsultationsdokument 2026 der Regierung nennen ein konkretes Mandatsdatum für Malta"]]', 'Anders als bei Litauens umstrittener "2028"-Zahl sind Maltas eigene Quellen konsistent und eindeutig: Es gibt überhaupt kein inländisches Zieldatum, nur eine Ausrichtung an der EU-Untergrenze von 2030.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'MT' AND cd.section = 'scope_transmission' AND dct.title = 'What MTCA says about the future';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '⚖️ Es gibt kein Bußgeldregime — es gibt nichts zu sanktionieren', NULL, NULL, 'Malta hat kein B2B-E-Invoicing-Mandat, keine lieferantenseitige B2G-Pflicht und keine Anforderung zur digitalen Meldung — daher gibt es keinen Bußgeldkatalog, der an eines davon anknüpft. Sowohl das Factsheet der Europäischen Kommission als auch die eigene Seite der MTCA bestätigen dies direkt, statt es der Vermutung zu überlassen.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'MT' AND cd.section = 'penalties_related' AND dct.title = '⚖️ No penalty regime exists — there is nothing to penalize';

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Wenn Sie an maltesische öffentliche Stellen verkaufen: E-Invoicing ist freiwillig, nicht verpflichtend', 'Maltesische Vergabestellen können strukturierte EN-16931-E-Rechnungen über Peppol empfangen, aber Sie sind gesetzlich nicht verpflichtet, sie zu versenden — Papier- oder PDF-Rechnungen bleiben zulässig, sofern eine bestimmte Vergabestelle nichts anderes verlangt.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'MT' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Wenn Sie einer maltesischen öffentlichen Stelle dennoch elektronisch fakturieren möchten, nutzen Sie Peppol', 'Übermitteln Sie über einen zertifizierten Peppol Access Point (Maltas Finanzministerium hat Pagero als Anbieter beauftragt) oder nutzen Sie, wo verfügbar, die manuelle Portal-Eingabeoption.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'MT' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Heute ist keine B2B-Maßnahme erforderlich', 'Es gibt kein inländisches B2B-E-Invoicing-Mandat, auf das man sich vorbereiten müsste, und die MTCA hat kein Zieldatum genannt, das über eine allgemeine Ausrichtung an der EU-ViDA-Untergrenze von 2030 hinausgeht.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'MT' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Beobachten Sie die MTCA im Hinblick auf den eventuellen inländischen Vorschlag', 'Verfolgen Sie direkt die Seite "E-Invoicing and DRR" auf mtca.gov.mt — sie ist die eindeutig klarste offizielle Quelle dafür, wann Maltas vorbereitende Phase in einen echten, terminierten Vorschlag übergeht.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'MT' AND sp.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Maltesische Steuer- und Zollbehörde (MTCA) -- E-Invoicing and DRR' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'MT' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Finanzministerium -- e-Invoicing' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'MT' AND pt.sort_order = 1;

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'mt-b2g-2018', 'de',
  'Öffentliche Vergabestellen müssen E-Rechnungen empfangen können',
  'Die Rechtsverordnungen zur Umsetzung der EU-Richtlinie 2014/55/EU wurden am 30. November 2018 veröffentlicht (laut dem eigenen Factsheet der Europäischen Kommission; Maltas offizielles Gesetzgebungsportal weist für die Durchführungsverordnung, Subsidiary Legislation 601.10, separat ein Inkrafttretensdatum von 19. Dezember 2018 aus — beide Daten werden hier festgehalten, statt eines stillschweigend zu bevorzugen), und änderten den Financial Administration and Audit Act (Cap. 174) sowie den Local Councils Act (Cap. 363). Dies ist KEIN Lieferantenmandat: Die verbindliche Pflicht besteht nur darin, dass maltesische zentrale, nachgeordnete und lokale Vergabestellen EN-16931-konforme E-Rechnungen für Beschaffungen oberhalb der EU-Schwellenwerte empfangen und verarbeiten können müssen — Lieferanten sind gesetzlich nicht zum Versand verpflichtet. Malta hat keine zentralisierte nationale Plattform; es stützt sich auf das Peppol-Netzwerk, wobei das Finanzministerium Pagero als zertifizierten Peppol-Dienstanbieter beauftragte, im Anschluss an das EU-geförderte Projekt "eInvoicing4Islands" (2019-2021).', '["Historischer Kontext — bestätigt, dass maltesische öffentliche Stellen E-Rechnungen empfangen KÖNNEN, nicht dass Lieferanten sie versenden müssen", "Lieferanten maltesischer öffentlicher Stellen können strukturierte EN-16931-E-Rechnungen über einen Peppol Access Point einreichen oder Rechnungen manuell über das jeweilige Portal eingeben"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'mt-b2g-subcentral-2020', 'de',
  'Frist zur Empfangsfähigkeit nachgeordneter Vergabestellen',
  'April 2020 wird von Branchenquellen wiederholt als der Zeitpunkt genannt, zu dem Maltas nachgeordnete öffentliche Vergabestellen in der Lage sein mussten, EN-16931-E-Rechnungen zu empfangen — konsistent mit der allgemeinen gestaffelten Fristenstruktur der EU-Richtlinie 2014/55/EU (zentrale Stellen bis 18. Apr. 2019, nachgeordnete bis 18. Apr. 2020), jedoch in dieser Rechercherunde auf keiner offiziellen maltesischen Regierungsseite explizit bestätigt gefunden, sodass es als aus Branchenquellen stammend und nicht als amtlich bestätigt festgehalten wird.', '[]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'mt-peppol-pagero', 'de',
  'Pagero als Maltas Peppol-Dienstanbieter beauftragt',
  'Im Rahmen des EU-geförderten Projekts "eInvoicing4Islands" (Juni 2019 bis etwa Q3 2021) führte das Finanzministerium eine öffentliche Ausschreibung durch und beauftragte Pagero mit der Bereitstellung von Maltas Peppol-Netzwerk- und E-Invoicing-Dienst — bestätigt durch Pageros eigene Pressemitteilung. Dies verschaffte Malta seine E-Invoicing-Infrastruktur, ohne eine eigene, maßgeschneiderte nationale Plattform zu errichten, anders als bei den meisten anderen erfassten EU-Ländern.', '[]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'mt-b2b-voluntary', 'de',
  'B2B-E-Invoicing bleibt freiwillig — kein Mandat, kein Zieldatum, kein Gesetzentwurf',
  'Malta hat kein Business-to-Business-E-Invoicing-Mandat und kein festgelegtes Datum für ein solches. Die eigene Seite der maltesischen Steuer- und Zollbehörde (MTCA) erklärt: "Die maltesische Steuer- und Zollbehörde (MTCA) prüft aktiv die Einführung von E-Invoicing und Echtzeit-Reporting... und stellt sicher, dass Malta bis 2030 ViDA-bereit ist" — vorbereitende Formulierungen, kein gesetzlich festgelegter Plan. Das eigene Factsheet der Europäischen Kommission bestätigt dasselbe: "kein Business-to-Business (B2B)-Mandat vorhanden... die Nutzung bleibt freiwillig." Es besteht kein Bußgeldregime für die Nichteinhaltung von E-Invoicing oder digitaler Meldung, da derzeit keine solche Pflicht besteht, deren Nichteinhaltung sanktioniert werden könnte.', '["Derzeit ist keine inländische B2B-E-Invoicing-Maßnahme erforderlich", "Beobachten Sie die MTCA (mtca.gov.mt) auf eine mögliche künftige Ankündigung eines inländischen Mandats — zum Zeitpunkt dieser Rechercherunde besteht keine solche"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'mt-vida-2030', 'de',
  'ViDA-grenzüberschreitende B2B-E-Rechnungsstellung und digitale Meldung werden verpflichtend (bestätigtes EU-Recht)',
  'Ab dem 1. Juli 2030 werden gemäß der Richtlinie (EU) 2025/516 des Rates die strukturierte E-Rechnungsstellung und die digitale Meldung für alle innergemeinschaftlichen B2B-Lieferungen verpflichtend. Dies ist genau das Datum, auf das sich auch die MTCA selbst als ihr "ViDA-bereit"-Ziel bezieht — Maltas eigene öffentliche Erklärungen beschreiben eine Arbeit auf diese EU-Untergrenze hin, nicht auf ein früheres inländisches Mandat.', '["Bereiten Sie sich auf die verpflichtende strukturierte E-Rechnungsstellung für den gesamten innergemeinschaftlichen B2B-Handel ab Mitte 2030 vor", "Maltas derzeitige Infrastruktur (Peppol über Pagero, aus dem B2G-Rollout) bietet eine technische Ausgangsbasis, auch wenn bislang kein inländischer B2B-Rollout-Plan existiert"]'
);

INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES (
  '2025-06-05-malta-tsi-project-closes', 'de',
  'Malta schließt sein Echtzeit-Reporting-Pilotprojekt ab — weiterhin kein B2B-Mandat in Sicht',
  'Maltas Steuerbehörde schloss ein EU-gefördertes Projekt zur Bereitschaft für Echtzeit-Reporting ab und bekräftigte, dass das Land E-Invoicing und digitale Meldung lediglich "aktiv prüft", ohne inländisches B2B-Mandat, Zieldatum oder Gesetzentwurf — mit dem Ziel einer allgemeinen Bereitschaft bis zur ViDA-Frist der EU im Jahr 2030.',
  '<h3>🇲🇹 Malta schließt sein Echtzeit-Reporting-Pilotprojekt ab — weiterhin kein B2B-Mandat in Sicht</h3>
<p>Am 5. Juni 2025 hielt die maltesische Steuer- und Zollbehörde (MTCA) die Abschlussveranstaltung mit Stakeholdern für ein EU-Projekt des Technical Support Instrument (TSI), "Stärkung der Steuer-Compliance durch Echtzeit-Reporting in Malta", ab. Es ist der konkreteste jüngste Beleg für Maltas Haltung zum E-Invoicing: erkundend, nicht verbindlich. Die eigene Seite der MTCA erklärt unmissverständlich, dass sie "aktiv die Einführung von E-Invoicing und Echtzeit-Reporting prüft", mit dem ausdrücklichen Ziel, "sicherzustellen, dass Malta bis 2030 ViDA-bereit ist" — kein früheres inländisches Mandat.</p>
<p>Damit hat Malta eines der schwächsten E-Invoicing-Regime unter den erfassten EU-Ländern: Rechtsverordnungen aus Ende 2018 verlangen von öffentlichen Vergabestellen, strukturierte E-Rechnungen *empfangen zu können*, doch Lieferanten sind nicht zum Versand verpflichtet, es gibt kein inländisches B2B-Mandat jeglicher Art, und Malta betreibt keine eigene Plattform — stattdessen verlässt es sich auf das Peppol-Netzwerk über einen beauftragten Dienstanbieter (Pagero). Sowohl das eigene Factsheet der Europäischen Kommission als auch die Seite der MTCA bestätigen, dass auch kein Bußgeldregime existiert, aus dem einfachen Grund, dass noch kein Mandat besteht, das durchzusetzen wäre.</p>'
);


-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr',
  'Pas d''obligation B2B, pas de système national de déclaration — le B2G n''est qu''une exigence de capacité de réception',
  'Cette page d''analyse reflète le régime de facturation électronique de Malte, tel que confirmé via la fiche pays de facturation électronique de la Commission européenne pour Malte, la page e-Invoicing du ministère des Finances de Malte et la page « E-Invoicing and DRR » de l''Administration fiscale et douanière de Malte (MTCA) elle-même (relue et confirmée de manière indépendante lors de cette série de recherches), à la date du 10 août 2026, et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Confirmez les exigences en vigueur directement auprès de la MTCA (mtca.gov.mt) ou d''un conseiller fiscal maltais avant de fonder vos décisions de conformité sur cette page.',
  'Malte a transposé la directive européenne de facturation électronique B2G par des avis juridiques fin 2018 — mais même cette obligation est plus étroite que celle de la plupart de ses pairs de l''UE : elle exige seulement que les pouvoirs adjudicateurs publics *soient en mesure de recevoir* des factures électroniques structurées, non que les fournisseurs les envoient. Malte n''a jamais mis en place d''obligation nationale de facturation électronique B2B, de plateforme de clearance, ni de système de contrôle continu des transactions. À la date de cette série de recherches, l''Administration fiscale et douanière de Malte se décrit elle-même comme « étudiant activement » la facturation électronique et le reporting en temps réel, visant à être prête pour le plancher ViDA de l''UE de 2030 plutôt que pour une obligation nationale antérieure.',
  'Malte accepte les factures électroniques structurées conformes à la norme EN 16931 pour le B2G, transmises via le réseau Peppol (Peppol BIS Billing 3.0, UBL) au moyen d''un point d''accès certifié, ou saisies manuellement via un portail. Malte ne dispose pas de plateforme nationale de facturation électronique propre — le ministère des Finances a plutôt confié à Pagero, en tant que prestataire de services Peppol certifié, cette mission à la suite d''un projet d''infrastructure financé par l''UE. Il n''existe aucun format de déclaration distinct à décrire, car Malte ne dispose d''aucun système national de déclaration.',
  'Le champ d''application du B2G ne couvre que le côté réception : les pouvoirs adjudicateurs doivent être en mesure de traiter les factures électroniques pour les marchés publics dépassant les seuils de l''UE ; les fournisseurs ne sont pas tenus de les envoyer. Il n''existe aujourd''hui aucun champ d''application de la facturation électronique B2B ou B2C, faute d''obligation.',
  'Pour la plupart des entreprises maltaises, il n''y a véritablement rien à faire aujourd''hui en matière de facturation électronique au-delà d''une prise de conscience générale — la tâche pratique consiste à surveiller l''éventuelle proposition nationale de la MTCA plutôt qu''à se préparer à une obligation existante.',
  'Il n''existe à Malte aucun régime de sanctions relatif à la facturation électronique ou à la déclaration numérique — confirmé à la fois par la fiche de la Commission européenne et par la propre page de la MTCA. Cela découle directement de l''absence d''obligation B2B et d''obligation B2G côté fournisseur à sanctionner.',
  'Malte dispose du régime de facturation électronique le plus réduit de tous les États membres de l''UE suivis sur ce site : la facturation électronique B2G exige seulement que les pouvoirs adjudicateurs puissent recevoir des factures structurées (avis juridiques, fin 2018) — il n''existe aucune obligation pour le fournisseur, aucune exigence nationale B2B, aucune plateforme de clearance et aucun système de déclaration de quelque nature que ce soit. L''Administration fiscale et douanière de Malte confirme qu''elle « étudie activement » la facturation électronique et le reporting en temps réel dans le but d''être « prête pour ViDA en 2030 », plutôt que de poursuivre une obligation nationale antérieure. Le plancher confirmé à l''échelle de l''UE demeure le 1er juillet 2030 (ViDA) pour le B2B transfrontalier.',
  '🇲🇹'
FROM countries WHERE code = 'MT';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '30 nov. 2018', 'Avis juridiques transposant la directive européenne de facturation électronique B2G' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'MT' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', 'Réception uniquement', 'Les autorités doivent accepter les factures électroniques — les fournisseurs ne sont pas tenus de les envoyer' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'MT' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', 'Aucune obligation', 'Aucune obligation de facturation électronique B2B, aucune date cible, aucun projet de loi' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'MT' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', 'Aucune plateforme', 'Peppol uniquement, via Pagero — aucun système national propre' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'MT' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '2030', '« Prête pour ViDA » est l''objectif déclaré par la MTCA elle-même, selon son propre site web' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'MT' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Format et réseau B2G', '[["Format", "Facture électronique structurée conforme à la norme EN 16931"], ["Réseau", "Peppol (Peppol BIS Billing 3.0, UBL) — aucune plateforme nationale propre"], ["Prestataire de services", "Pagero, mandaté par le ministère des Finances à la suite du projet financé par l''UE \"eInvoicing4Islands\""], ["Options de soumission", "Transmission structurée via un point d''accès Peppol certifié, ou saisie manuelle via un portail"]]', 'Malte fait figure d''exception parmi les pays de l''UE suivis en n''ayant construit aucune plateforme propre — elle dépend entièrement du réseau Peppol partagé et d''un unique prestataire de services mandaté.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'MT' AND cd.section = 'file_format' AND dct.title = 'B2G format & network';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Ce qui est réellement exigé aujourd''hui', '[["Pouvoirs adjudicateurs", "Doivent être en mesure de recevoir et de traiter les factures électroniques EN 16931 pour les marchés publics dépassant les seuils de l''UE — depuis nov./déc. 2018 (administration centrale), avr. 2020 (infra-centrale, source sectorielle)"], ["Fournisseurs des organismes publics", "PAS tenus d''envoyer des factures électroniques — peuvent continuer à soumettre du papier/PDF"], ["B2B", "Aucune exigence d''aucune sorte — entièrement facultatif, par accord mutuel"], ["B2C", "N''est couvert par aucune règle"]]', 'Il s''agit de l''obligation B2G la plus étroite de tous les pays de l''UE suivis sur ce site — la plupart des pairs exigent à la fois une capacité de réception ET une obligation d''envoi côté fournisseur ; Malte n''a que la première.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'MT' AND cd.section = 'scope_transmission' AND dct.title = 'What''s actually required today';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Ce que dit la MTCA sur l''avenir', '[["Statut", "\"Étudie activement la mise en œuvre de la facturation électronique et du reporting en temps réel\" (propres termes de la MTCA)"], ["Objectif", "\"Garantir que Malte soit prête pour ViDA d''ici 2030\" (propres termes de la MTCA)"], ["Activité récente", "Le projet financé par le TSI \"Renforcer la conformité fiscale grâce au reporting en temps réel à Malte\" a tenu un événement de clôture avec les parties prenantes le 5 juin 2025"], ["Aucune date nationale engagée", "Ni le plan stratégique 2023-2025 de la MTCA ni le document de consultation prébudgétaire 2026 du gouvernement ne mentionnent une date précise d''obligation pour Malte"]]', 'Contrairement au chiffre contesté de « 2028 » pour la Lituanie, les propres sources de Malte sont cohérentes et sans ambiguïté : il n''existe aucune date cible nationale, seulement un alignement sur le plancher de l''UE de 2030.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'MT' AND cd.section = 'scope_transmission' AND dct.title = 'What MTCA says about the future';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '⚖️ Aucun régime de sanctions n''existe — il n''y a rien à sanctionner', NULL, NULL, 'Malte n''a aucune obligation de facturation électronique B2B, aucune obligation B2G côté fournisseur, et aucune exigence de déclaration numérique — il n''existe donc aucun barème de sanctions rattaché à l''un ou l''autre. La fiche de la Commission européenne et la propre page de la MTCA le confirment toutes deux directement, plutôt que de le laisser à la déduction.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'MT' AND cd.section = 'penalties_related' AND dct.title = '⚖️ No penalty regime exists — there is nothing to penalize';

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Si vous vendez à des organismes publics maltais, sachez que la facturation électronique est facultative, non obligatoire', 'Les pouvoirs adjudicateurs maltais peuvent recevoir des factures électroniques structurées EN 16931 via Peppol, mais vous n''êtes pas légalement tenu de les envoyer — les factures papier ou PDF restent acceptables, sauf demande contraire d''un pouvoir adjudicateur spécifique.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'MT' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Si vous souhaitez tout de même facturer électroniquement un organisme public maltais, utilisez Peppol', 'Soumettez via un point d''accès Peppol certifié (le ministère des Finances de Malte a mandaté Pagero comme prestataire) ou utilisez l''option de saisie manuelle via le portail, lorsqu''elle est disponible.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'MT' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Aucune action B2B n''est requise aujourd''hui', 'Il n''existe aucune obligation nationale de facturation électronique B2B à laquelle se préparer, et la MTCA n''a indiqué aucune date cible au-delà d''un alignement général sur le plancher ViDA de l''UE de 2030.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'MT' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Surveillez la MTCA pour l''éventuelle proposition nationale', 'Surveillez directement la page « E-Invoicing and DRR » de mtca.gov.mt — c''est de loin la source officielle la plus claire pour savoir quand la phase préparatoire de Malte se transformera en une proposition réelle et datée.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'MT' AND sp.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Administration fiscale et douanière de Malte -- E-Invoicing and DRR' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'MT' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Ministère des Finances -- e-Invoicing' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'MT' AND pt.sort_order = 1;

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'mt-b2g-2018', 'fr',
  'Les pouvoirs adjudicateurs publics doivent être en mesure de recevoir des factures électroniques',
  'Les avis juridiques transposant la directive européenne 2014/55/UE ont été publiés le 30 novembre 2018 (selon la fiche de la Commission européenne elle-même ; le portail législatif officiel de Malte indique par ailleurs une date de promulgation du 19 décembre 2018 pour le règlement d''application, Subsidiary Legislation 601.10 — les deux dates sont mentionnées ici plutôt que de n''en retenir qu''une silencieusement), modifiant le Financial Administration and Audit Act (Cap. 174) et le Local Councils Act (Cap. 363). Il ne s''agit PAS d''une obligation pour le fournisseur : l''obligation contraignante est uniquement que les pouvoirs adjudicateurs maltais centraux, infra-centraux et locaux soient en mesure de recevoir et de traiter des factures électroniques conformes à la norme EN 16931 pour les marchés publics dépassant les seuils de l''UE — les fournisseurs ne sont pas légalement tenus de les envoyer. Malte ne dispose d''aucune plateforme nationale centralisée ; elle s''appuie sur le réseau Peppol, le ministère des Finances ayant mandaté Pagero comme prestataire de services Peppol certifié à la suite du projet financé par l''UE « eInvoicing4Islands » (2019-2021).', '["Contexte historique — confirme que les organismes publics maltais PEUVENT recevoir des factures électroniques, non que les fournisseurs doivent les envoyer", "Les fournisseurs d''organismes publics maltais peuvent soumettre des factures électroniques structurées EN 16931 via un point d''accès Peppol ou saisir les factures manuellement via le portail concerné"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'mt-b2g-subcentral-2020', 'fr',
  'Échéance de capacité de réception des pouvoirs adjudicateurs infra-centraux',
  'Avril 2020 est cité de manière répétée par des sources sectorielles comme la date à laquelle les pouvoirs adjudicateurs publics infra-centraux de Malte devaient être en mesure de recevoir des factures électroniques EN 16931 — conforme à la structure générale des échéances échelonnées de la directive européenne 2014/55/UE (organismes centraux avant le 18 avr. 2019, infra-centraux avant le 18 avr. 2020), mais non trouvée explicitement mentionnée sur une page officielle du gouvernement maltais lors de cette série de recherches ; elle est donc consignée comme provenant d''une source sectorielle plutôt que confirmée officiellement.', '[]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'mt-peppol-pagero', 'fr',
  'Pagero mandaté comme prestataire de services Peppol de Malte',
  'Dans le cadre du projet financé par l''UE « eInvoicing4Islands » (de juin 2019 à environ le troisième trimestre 2021), le ministère des Finances a mené un appel d''offres public et mandaté Pagero pour assurer le service de réseau Peppol et de facturation électronique de Malte — confirmé par le communiqué de presse de Pagero lui-même. Cela a permis à Malte de disposer de son infrastructure de facturation électronique sans construire de plateforme nationale sur mesure, contrairement à la plupart des autres pays de l''UE suivis.', '[]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'mt-b2b-voluntary', 'fr',
  'La facturation électronique B2B reste facultative — aucune obligation, aucune date cible, aucun projet de loi',
  'Malte n''a aucune obligation de facturation électronique interentreprises et aucune date engagée pour en instaurer une. La propre page de l''Administration fiscale et douanière de Malte (MTCA) indique : « L''Administration fiscale et douanière de Malte (MTCA) étudie activement la mise en œuvre de la facturation électronique et du reporting en temps réel... afin de garantir que Malte soit prête pour ViDA d''ici 2030 » — une formulation préparatoire, non un plan légiféré. La propre fiche de la Commission européenne confirme la même chose : « aucune obligation interentreprises (B2B) en vigueur... l''utilisation reste facultative ». Aucun régime de sanctions n''existe en cas de non-conformité en matière de facturation électronique ou de déclaration numérique, car aucune obligation de ce type n''existe actuellement à faire respecter.', '["Aucune action de facturation électronique B2B nationale n''est requise aujourd''hui", "Surveillez la MTCA (mtca.gov.mt) pour toute future annonce d''obligation nationale — aucune n''existe à la date de cette série de recherches"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'mt-vida-2030', 'fr',
  'La facturation électronique B2B transfrontalière et la déclaration numérique ViDA deviennent obligatoires (droit de l''UE confirmé)',
  'À compter du 1er juillet 2030, en vertu de la directive (UE) 2025/516 du Conseil, la facturation électronique structurée et la déclaration numérique deviennent obligatoires pour toutes les livraisons B2B intracommunautaires. C''est exactement la date à laquelle la MTCA elle-même fait référence comme son objectif « prête pour ViDA » — les propres déclarations publiques de Malte décrivent un travail en vue de ce plancher de l''UE, non d''une obligation nationale antérieure.', '["Préparez-vous à la facturation électronique structurée obligatoire pour l''ensemble du commerce B2B intra-UE à partir de mi-2030", "L''infrastructure actuelle de Malte (Peppol via Pagero, issue du déploiement B2G) offre une base technique de départ, bien qu''aucun plan de déploiement B2B national n''existe encore"]'
);

INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES (
  '2025-06-05-malta-tsi-project-closes', 'fr',
  'Malte clôture son projet pilote de reporting en temps réel — toujours aucune obligation B2B à l''ordre du jour',
  'L''administration fiscale de Malte a clôturé un projet financé par l''UE portant sur la préparation au reporting en temps réel, réaffirmant que le pays « étudie activement » seulement la facturation électronique et la déclaration numérique, sans obligation B2B nationale, date cible ou projet de loi — visant plutôt une préparation générale pour l''échéance ViDA de l''UE de 2030.',
  '<h3>🇲🇹 Malte clôture son projet pilote de reporting en temps réel — toujours aucune obligation B2B à l''ordre du jour</h3>
<p>Le 5 juin 2025, l''Administration fiscale et douanière de Malte (MTCA) a tenu l''événement de clôture avec les parties prenantes d''un projet du Technical Support Instrument (TSI) de l''UE, « Renforcer la conformité fiscale grâce au reporting en temps réel à Malte ». C''est la preuve récente la plus concrète de la position de Malte sur la facturation électronique : exploratoire, non engageante. La propre page de la MTCA indique clairement qu''elle « étudie activement la mise en œuvre de la facturation électronique et du reporting en temps réel », avec pour objectif explicite de « garantir que Malte soit prête pour ViDA d''ici 2030 » — non une obligation nationale antérieure.</p>
<p>Cela laisse Malte avec l''un des régimes de facturation électronique les plus réduits parmi les pays de l''UE suivis : des avis juridiques de fin 2018 exigent que les pouvoirs adjudicateurs publics *soient en mesure de recevoir* des factures électroniques structurées, mais les fournisseurs ne sont pas tenus de les envoyer, il n''existe aucune obligation B2B nationale d''aucune sorte, et Malte n''exploite aucune plateforme propre — s''appuyant plutôt sur le réseau Peppol via un prestataire de services mandaté (Pagero). La fiche de la Commission européenne elle-même et la page de la MTCA confirment toutes deux qu''aucun régime de sanctions n''existe non plus, pour la simple raison qu''aucune obligation n''existe encore à faire respecter.</p>'
);
